import {zipSync,strToU8} from 'fflate';
export const officeZip=files=>Buffer.from(zipSync(Object.fromEntries(Object.entries(files).map(([name,value])=>[name,typeof value==='string'?strToU8(value):value]))));
export function makeUnicodePdf(text='中文办公'){
 const chars=[...text],codes=chars.map((_,index)=>(index+1).toString(16).padStart(4,'0'));
 const cmap=`/CIDInit /ProcSet findresource begin 12 dict begin begincmap /CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def /CMapName /Fixture def /CMapType 2 def 1 begincodespacerange <0000> <FFFF> endcodespacerange ${chars.length} beginbfchar ${chars.map((char,index)=>`<${codes[index]}> <${char.charCodeAt(0).toString(16).padStart(4,'0')}>`).join(' ')} endbfchar endcmap CMapName currentdict /CMap defineresource pop end end`;
 const stream=`BT /F1 12 Tf 72 720 Td <${codes.join('')}> Tj ET`,objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 7 0 R >>','<< /Type /Font /Subtype /Type0 /BaseFont /Fixture /Encoding /Identity-H /DescendantFonts [5 0 R] /ToUnicode 6 0 R >>','<< /Type /Font /Subtype /CIDFontType2 /BaseFont /Fixture /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /DW 1000 >>',`<< /Length ${Buffer.byteLength(cmap)} >>\nstream\n${cmap}\nendstream`,`<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`];
 let document='%PDF-1.4\n';const offsets=[];objects.forEach((body,index)=>{offsets.push(Buffer.byteLength(document));document+=`${index+1} 0 obj\n${body}\nendobj\n`;});const xref=Buffer.byteLength(document);document+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.map(offset=>`${String(offset).padStart(10,'0')} 00000 n \n`).join('')}trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return Buffer.from(document);
}
export function makePdf(text='LOCAL DOCUMENT TEST',url='http://127.0.0.1:9/not-visited'){
 const safe=text.replace(/[\\()]/g,'\\$&'),stream=`BT /F1 12 Tf 72 720 Td (${safe}) Tj ET`;
 const objects=[`<< /Type /Catalog /Pages 2 0 R /OpenAction << /S /JavaScript /JS (app.launchURL\(\"${url}\"\)) >> >>`,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R /Annots [6 0 R] >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`,`<< /Type /Annot /Subtype /Link /Rect [72 700 180 730] /A << /S /URI /URI (${url}) >> >>`];
 let document='%PDF-1.4\n';const offsets=[0];objects.forEach((body,index)=>{offsets.push(Buffer.byteLength(document));document+=`${index+1} 0 obj\n${body}\nendobj\n`;});const xref=Buffer.byteLength(document);document+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(offset=>`${String(offset).padStart(10,'0')} 00000 n \n`).join('')}trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return Buffer.from(document);
}
